// ===== CONTROL PANEL =====
const CONFIG = { dryRun: true, maxPerCycle: 2, fu2Days: 3, fu3Days: 7, coldDays: 14,
                 days: [1,2,3,4,5], startHour: 8, endHour: 18, tz: 'Europe/London' };
// =========================
// Weekday business hours by default, unlike the DM workflows. An Instagram DM at
// 9pm reads as casual; an email at 9pm reads as a mass send.

const EXCLUDE_CONTACT_IDS = [];   // TODO: must match the setter and day-1 lists
const EXCLUDE_NAMES = ["ai chat", "chat ai", "chat al"];

const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: CONFIG.tz }));
if (!CONFIG.days.includes(localNow.getDay())) return [];
if (localNow.getHours() < CONFIG.startHour || localNow.getHours() >= CONFIG.endHour) return [];

const sd = $getWorkflowStaticData('global');
sd.ladder = sd.ladder || {};   // conversationId -> { fu2: ts, fu3: ts, cold: ts }

const convs = ($input.first().json.conversations) || [];
const DAY = 86400000;
const out = [];

for (const c of convs) {
  if (c.lastMessageType !== 'TYPE_INSTAGRAM') continue;
  if (c.lastMessageDirection !== 'outbound') continue;      // they still haven't replied
  if (EXCLUDE_CONTACT_IDS.includes(c.contactId)) continue;
  const name = (c.contactName || c.fullName || '').toLowerCase();
  if (EXCLUDE_NAMES.some(b => name.includes(b))) continue;

  const last = Number(c.lastMessageDate || 0);
  if (!last) continue;
  const days = (Date.now() - last) / DAY;
  if (days < CONFIG.fu2Days) continue;                       // day-1 workflow owns anything younger
  if (days > CONFIG.coldDays + 7) continue;                  // ancient: leave it alone entirely

  const state = sd.ladder[c.id] || {};
  let step = null;
  if (days >= CONFIG.coldDays && !state.cold) step = 'cold';
  else if (days >= CONFIG.fu3Days && !state.fu3) step = 'fu3';
  else if (days >= CONFIG.fu2Days && !state.fu2) step = 'fu2';
  if (!step) continue;                                       // this rung already sent

  out.push({ json: {
    conversationId: c.id, contactId: c.contactId,
    contactName: c.contactName || c.fullName || c.id,
    lastMessageDate: last, daysQuiet: Math.round(days * 10) / 10,
    step, dryRun: CONFIG.dryRun,
  }});
}
return out.slice(0, CONFIG.maxPerCycle);

// Same guards as the DM workflows. An email under the MadeEA name is still a
// message under the MadeEA name, so the Fact Pack and category rules hold.
// The only relaxation is length: 3 sentences instead of 2, because an email with
// a channel-switch line in it cannot land the point in two.

function hasPlaceholder(s) {
  const t = String(s);
  if (/\[[^\]]*\]|\{\{|\}\}|<[a-z_]+>/i.test(t)) return true;
  if (/\b(your business name|business name here|their name|insert |name here|first name)\b/i.test(t)) return true;
  return false;
}
function oneMarker(s) {
  const RE = /([\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}]\u{FE0F}?|:-?\)|:-?\(|;-?\)|:D)/gu;
  let n = 0;
  return s.replace(RE, m => (++n === 1 ? m : '')).replace(/ {2,}/g, ' ').replace(/\s+([.!?,])/g, '$1').trim();
}
function stripControl(s) {
  s = s.replace(/<(\w+:[\w:]+)>[\s\S]*?<\/\1>/g, '');
  s = s.replace(/<budget:[\s\S]*$/i, '');
  s = s.replace(/<\/?\w+:[\w:.\-]*[^>]*>/g, '');
  return s.replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/[ \t]{2,}/g, ' ').trim();
}
function isBannedCategory(s) {
  const t = String(s).toLowerCase();
  if (/\bv\.?a\.?s?\b/.test(t) && !/\bvalue\b/.test(t)) return true;
  if (/\bvirtual assistants?\b/.test(t)) return true;
  if (/\b(outsourc|offshor)(e|ed|ing)\b/.test(t)) return true;
  return false;
}
function isUnapprovedPrice(s) {
  const APPROVED = /^(3,?000|3k|2,?250)$/i;
  const nums = String(s).match(/(?:\$|usd\s*|\u00a3|\u20ac)\s?([\d,]+(?:\.\d+)?k?)/gi) || [];
  for (const n of nums) if (!APPROVED.test(n.replace(/[^\d,.k]/gi, ''))) return true;
  if (/\b\d{1,2}\s?%\s?(off|discount)\b/i.test(String(s))) return true;
  return false;
}
// Fragments must contain a letter: the splitter breaks after "?", so a trailing
// emoji would otherwise count as a phantom extra sentence.
function isTooLong(s) {
  if (/\$\s?(3,?000|2,?250)/i.test(s)) return false;
  return String(s).split(/(?<=[.!?])\s+/).filter(x => /[a-z]/i.test(x)).length > 3;
}
function isIdentityLeak(s) {
  return /\b(as an ai|i am an ai|i'm an ai|language model|chatbot|automated assistant)\b/i.test(String(s));
}
function isFalsePromise(s) {
  return /\b(just (sent|emailed|shared)|i('ve| have) (sent|emailed|attached|booked)|sending (it|that) (over|now)|added you to)\b/i.test(String(s));
}

const SUBJECTS = { fu2: 'Following up from Instagram', fu3: 'Last one from me' };

const reqs = $('Build Follow-up').all().filter(it => it.json.send);
const ors = $input.all();
const out = [];

for (let i = 0; i < ors.length; i++) {
  const ctx = reqs[i].json;
  const r = ors[i].json;
  const base = { conversationId: ctx.conversationId, contactId: ctx.contactId, contactName: ctx.contactName,
                 email: ctx.email, step: ctx.step, daysQuiet: ctx.daysQuiet, dryRun: ctx.dryRun };

  let draft = (Array.isArray(r.content) ? r.content.filter(b => b && b.type === 'text').map(b => b.text).join('') : '').trim();
  if (!draft) continue;
  if (/^<SKIP/i.test(draft)) { out.push({ json: { ...base, send: false, tag: 'madeea-setter-deciding' } }); continue; }

  draft = oneMarker(stripControl(draft.replace(/\s*\n+\s*/g, ' ')));
  if (!draft) continue;

  const failed = hasPlaceholder(draft) ? 'placeholder'
    : isBannedCategory(draft) ? 'banned-category'
    : isUnapprovedPrice(draft) ? 'unapproved-price'
    : isTooLong(draft) ? 'too-long'
    : isIdentityLeak(draft) ? 'identity-leak'
    : isFalsePromise(draft) ? 'false-promise'
    : null;
  if (failed) { out.push({ json: { ...base, send: false, tag: 'madeea-setter-needs-human', reason: failed, draft } }); continue; }

  out.push({ json: { ...base, send: true, subject: SUBJECTS[ctx.step] || 'Following up',
    message: draft, tag: ctx.step === 'fu2' ? 'madeea-setter-fu2' : 'madeea-setter-fu3' } });
}
return out;

// Record the rung so it can never fire twice, and so the ladder advances rather
// than restarting. Dry runs deliberately record nothing.
const sd = $getWorkflowStaticData('global');
sd.ladder = sd.ladder || {};
for (const item of $input.all()) {
  const j = item.json;
  if (j.dryRun) continue;
  const s = sd.ladder[j.conversationId] || {};
  s[j.step] = Date.now();
  sd.ladder[j.conversationId] = s;
}
return $input.all();

