sd.ladder = sd.ladder || {};
for (const item of $input.all()) {
  const j = item.json;
  if (j.dryRun) continue;
  const s = sd.ladder[j.conversationId] || {};
  s[j.step] = Date.now();
  sd.ladder[j.conversationId] = s;
}
return $input.all();
